                           ">
                            <i class="fab fa-chrome"></i> Chrome
                        </a>
                        <a href="https://www.mozilla.org/firefox/" 
                           target="_blank"
                           style="
                               background: #ff7139;
                               color: white;
                               padding: 10px 20px;
                               border-radius: 5px;
                               text-decoration: none;
                               display: flex;
                               align-items: center;
                               gap: 8px;
                           ">
                            <i class="fab fa-firefox"></i> Firefox
                        </a>
                    </div>
                </div>
            </div>
        `;

        document.body.innerHTML = warningHTML;
    }

    /**
     * 初始化所有模块
     */
    initModules() {
        try {
            // 初始化存储管理器
            this.storageManager = StorageManager;

