     */
    start() {
        try {
            // 初始化UI管理器
            this.uiManager.init(this.recordsManager, this.statsCalculator);

            // 添加启动动画
            this.addStartupAnimation();

            // 显示欢迎消息
            setTimeout(() => {
                this.showWelcomeMessage();
            }, 1000);

            // 添加页面可见性变化监听
            this.addVisibilityChangeListener();

            // 添加离线检测
            this.addOfflineDetection();

            // 添加服务工作者（如果支持）
            this.registerServiceWorker();

