        // 为按钮添加渐入动画
        const buttons = document.querySelectorAll('.btn-primary, .btn-secondary');
        buttons.forEach((button, index) => {
            button.style.opacity = '0';

            setTimeout(() => {
                button.style.transition = 'opacity 0.5s ease';
                button.style.opacity = '1';
            }, 500 + (index * 100));
        });
    }

